-- Rollback for 20261031184935_DropFgsVehicleTables
-- Recreates empty setup vehicle tables (data lives in inventory after MoveFgsVehicleFromSetup).
START TRANSACTION;

CREATE TABLE IF NOT EXISTS setup."FgsVehicle" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "TenantId" bigint NOT NULL,
    "CompanyId" bigint NOT NULL,
    "InventoryLocationId" bigint NOT NULL,
    "OwnershipType" character varying(20) NOT NULL DEFAULT 'Owned',
    "OwnershipCompany" character varying(200),
    "Year" smallint,
    "Make" character varying(100),
    "Model" character varying(100),
    "Color" character varying(50),
    "VIN" character varying(50) NOT NULL,
    "LicensePlate" character varying(50),
    "LicensePlateState" character varying(50),
    "PurchaseDate" date,
    "PurchasePrice" numeric(18,2),
    "PurchasedFrom" character varying(200),
    "IsPurchasedNew" boolean,
    "Notes" text,
    "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
    "CreatedBy" character varying(100),
    "UpdatedOn" timestamptz,
    "UpdatedBy" character varying(100),
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    CONSTRAINT "PK_FgsVehicle" PRIMARY KEY ("Id"),
    CONSTRAINT "UQ_FgsVehicle_InventoryLocationId" UNIQUE ("InventoryLocationId"),
    CONSTRAINT "CK_FgsVehicle_OwnershipType" CHECK ("OwnershipType" IN ('Owned', 'Leased', 'Rented')),
    CONSTRAINT "FK_FgsVehicle_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES setup."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS setup."FgsVehicleMaintenance" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "TenantId" bigint NOT NULL,
    "CompanyId" bigint NOT NULL,
    "VehicleId" bigint NOT NULL,
    "VehicleMaintenanceTypeId" integer NOT NULL,
    "ServiceDate" date NOT NULL,
    "MileageAtService" integer,
    "ServiceProvider" character varying(200),
    "InvoiceNumber" character varying(100),
    "Cost" numeric(18,2),
    "NextServiceDate" date,
    "NextServiceMileage" integer,
    "IsCompleted" boolean NOT NULL DEFAULT TRUE,
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "Description" character varying(500),
    "Notes" text,
    "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
    "CreatedBy" character varying(100),
    "UpdatedOn" timestamptz,
    "UpdatedBy" character varying(100),
    CONSTRAINT "PK_FgsVehicleMaintenance" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_FgsVehicleMaintenance_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES setup."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT,
    CONSTRAINT "FK_FgsVehicleMaintenance_FgsVehicle_VehicleId" FOREIGN KEY ("VehicleId") REFERENCES setup."FgsVehicle" ("Id") ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS "IX_FgsVehicle_TenantId_CompanyId_InventoryLocationId" ON setup."FgsVehicle" ("TenantId", "CompanyId", "InventoryLocationId");
CREATE INDEX IF NOT EXISTS "IX_FgsVehicle_TenantId_CompanyId_IsActive" ON setup."FgsVehicle" ("TenantId", "CompanyId", "IsActive");
CREATE INDEX IF NOT EXISTS "IX_FgsVehicleMaintenance_TenantId_CompanyId_IsActive" ON setup."FgsVehicleMaintenance" ("TenantId", "CompanyId", "IsActive");
CREATE INDEX IF NOT EXISTS "IX_FgsVehicleMaintenance_TenantId_CompanyId_IsCompleted" ON setup."FgsVehicleMaintenance" ("TenantId", "CompanyId", "IsCompleted");
CREATE INDEX IF NOT EXISTS "IX_FgsVehicleMaintenance_TenantId_CompanyId_NextServiceDate" ON setup."FgsVehicleMaintenance" ("TenantId", "CompanyId", "NextServiceDate");
CREATE INDEX IF NOT EXISTS "IX_FgsVehicleMaintenance_TenantId_CompanyId_ServiceDate" ON setup."FgsVehicleMaintenance" ("TenantId", "CompanyId", "ServiceDate");
CREATE INDEX IF NOT EXISTS "IX_FgsVehicleMaintenance_TenantId_CompanyId_VehicleId" ON setup."FgsVehicleMaintenance" ("TenantId", "CompanyId", "VehicleId");
CREATE INDEX IF NOT EXISTS "IX_FgsVehicleMaintenance_TenantId_CompanyId_VehicleMaintenanceTypeId" ON setup."FgsVehicleMaintenance" ("TenantId", "CompanyId", "VehicleMaintenanceTypeId");
CREATE INDEX IF NOT EXISTS "IX_FgsVehicleMaintenance_VehicleId" ON setup."FgsVehicleMaintenance" ("VehicleId");

DELETE FROM setup."__EFMigrationsHistory"
WHERE "MigrationId" = '20261031184935_DropFgsVehicleTables';

COMMIT;
